<script setup>
import { onUnmounted,ref,watch } from 'vue'; import { IonApp,IonRouterOutlet } from '@ionic/vue'; import { io } from '../../shared/realtime'; import { API_BASE } from './api'; import { useRoute } from 'vue-router';
const notice=ref(null),route=useRoute();let socket,timer;watch(()=>route.path,()=>{socket?.disconnect();const u=JSON.parse(localStorage.getItem('driverUser')||'null');if(!u)return;socket=io(API_BASE.replace('/api',''),{tokenKey:'driverToken'});socket.on('connect',()=>socket.emit('join-user',u.id));socket.on('notification',n=>{notice.value=n;clearTimeout(timer);timer=setTimeout(()=>notice.value=null,8000)});},{immediate:true});onUnmounted(()=>{socket?.disconnect();clearTimeout(timer)});
</script><template><ion-app><ion-router-outlet/><div v-if="notice" class="push-popup" :class="notice.level"><button @click="notice=null">×</button><small>FLOWDEPOT · NOW</small><b>{{notice.title}}</b><span>{{notice.message}}</span><em v-if="notice.simulation">🧪 Simulation notification</em></div></ion-app></template>